function invoicePaid(p,i){return (i.openingCredit||0)+sum((p.receipts||[]).filter(r=>r.invoiceCode===i.code),'amount')}
function invoiceBalance(p,i){return Math.max(0,Math.round((i.amount-invoicePaid(p,i))*100)/100)}
function financials(list=data.proposals){const a=list.filter(approval),invoices=a.flatMap(p=>(p.invoices||[]).map(i=>({...i,balance:invoiceBalance(p,i)})));return {contracted:sum(a,'netValue'),billed:a.reduce((n,p)=>n+sum(p.invoices||[],'amount'),0),received:sum(a,'receivedValue'),balance:sum(a,'netValue')-sum(a,'receivedValue'),upcoming:invoices.filter(i=>i.dueDate>=today()&&i.balance>0),overdue:invoices.filter(i=>i.dueDate<today()&&i.balance>0)}}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} ${type==='file'?'':'maxlength="500"'}></label>`}
function selectField(name,label,values,value,extra=''){return `<label>${label}<select name="${name}" ${extra}>${values.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function showModal(kind,title,html,button='Salvar'){formKind=kind;$('#modal-title').textContent=title;$('#fields').innerHTML=html;$('#form-error').textContent='';$('#submit').textContent=button;$('#submit').disabled=false;$('#submit').hidden=false;$('#cancel').textContent='Cancelar';$('#modal').showModal();decorateProtocols($('#fields'));bindFileDownloads($('#fields'))}
function clearAction(){clearTimeout(actionTimer);$('#action-bar').hidden=true;actionUndo=null}
