$('#keep-action').onclick=clearAction;
$('#undo-action').onclick=async()=>{if(!actionUndo||pending)return;try{await actionUndo();clearAction();toast('A ação foi desfeita.')}catch(e){toast(e.message)}};
async function save(message='As alterações foram salvas.'){
 if(pending)return false;pending=true;$('#submit').disabled=true;const before=structuredClone(durable),next=structuredClone(data);
 try{if(api){const r=await uploadWorkspace(next,revision);const payload=await r.json();if(!r.ok){if(r.status===409){const fresh=await fetchWorkspace();data=fresh.data;durable=structuredClone(data);revision=fresh.revision}throw Error(payload.error||'Não foi possível salvar.')}revision=payload.revision}else{if(localStorage.getItem(storageKey)!==JSON.stringify(durable))throw Error('Outra aba alterou os dados. Recarregue antes de continuar.');localStorage.setItem(storageKey,JSON.stringify(next))}data=next;durable=structuredClone(next);const savedRevision=revision;
 action(message,async()=>{if(api){const r=await fetch('/api/undo',{method:'PUT',headers:{'Content-Type':'application/json','If-Match':String(savedRevision)},body:'{}'});const payload=await r.json();if(!r.ok)throw Error(payload.error||'Não foi possível desfazer.');const fresh=await fetchWorkspace();data=fresh.data;revision=fresh.revision}else{if(localStorage.getItem(storageKey)!==JSON.stringify(next))throw Error('Os dados foram alterados. Recarregue para conferir.');localStorage.setItem(storageKey,JSON.stringify(before));data=structuredClone(before)}durable=structuredClone(data);render()});return true
 }catch(e){data=structuredClone(durable);$('#form-error').textContent=e.message;toast(e.message);render();return false}finally{pending=false;$('#submit').disabled=false}
}
function currentGroup(){return Object.entries(groupDefs).find(([id,g])=>g[2].includes(active))}
function usesWorkTab(id){return Boolean(modules[id])&&!['painel','recentes'].includes(id)}
const tabSessionKey='orionhub.workspace-tabs.v1';
let pinnedTabs=[],workTabs=[],tabViews={},tabPickerOpen=false,tabReady=false;
try{const saved=JSON.parse(sessionStorage.getItem(tabSessionKey)||'{}');workTabs=Array.isArray(saved.tabs)?[...new Set(saved.tabs.filter(usesWorkTab))]:[];pinnedTabs=Array.isArray(saved.pinned)?saved.pinned.filter(id=>workTabs.includes(id)):[];workTabs=[...workTabs.filter(id=>pinnedTabs.includes(id)),...workTabs.filter(id=>!pinnedTabs.includes(id))];tabViews=saved.views&&typeof saved.views==='object'?saved.views:{}}catch{}
function storeWorkTabs(){try{sessionStorage.setItem(tabSessionKey,JSON.stringify({tabs:workTabs,pinned:pinnedTabs,views:tabViews}))}catch{}}
function captureTabView(){if(!tabReady||!workTabs.includes(active))return;const company=$('#company-form');tabViews[active]={query,statusFilter,clientFilter,sortOrder,selected,analyticsFrom,analyticsTo,searchTags:structuredClone(searchTags),scroll:window.scrollY,companyDraft:company?Object.fromEntries(new FormData(company)):null};storeWorkTabs()}
function restoreTabView(id){const view=tabViews[id]||{};searchTags=Array.isArray(view.searchTags)?view.searchTags:[];renderSearchTags();query=view.query||'';statusFilter=view.statusFilter||'Todos';clientFilter=view.clientFilter||'';sortOrder=view.sortOrder||'recent';selected=view.selected||null;analyticsFrom=view.analyticsFrom||'';analyticsTo=view.analyticsTo||'';$('#search').value=query}
function renderWorkTabs(){const root=$('#workspace-tabs');root.innerHTML=`<div class="work-tab-list" role="tablist" aria-label="Páginas abertas">${workTabs.map(id=>`<div data-tab-id="${id}" class="work-tab ${pinnedTabs.includes(id)?'is-pinned':''} ${active===id?'is-active':''}"><button type="button" role="tab" aria-selected="${active===id}" data-work-tab="${id}" aria-label="${esc(pageLabel(id))}" title="${esc(pageLabel(id))}. Arraste para reordenar." tabindex="${active===id||!workTabs.includes(active)&&id===workTabs[0]?'0':'-1'}"><span>${esc(pageLabel(id))}</span></button><button type="button" class="work-tab-pin" data-pin-tab="${id}" aria-pressed="${pinnedTabs.includes(id)}" aria-label="${pinnedTabs.includes(id)?'Desafixar':'Fixar'} aba ${esc(pageLabel(id))}" title="${pinnedTabs.includes(id)?'Desafixar':'Fixar'} aba"><svg viewBox="0 0 24 24" fill="${pinnedTabs.includes(id)?'currentColor':'none'}" stroke="currentColor" stroke-width="1.5"><path d="M8 3h8l-1 7 4 4H5l4-4-1-7M12 14v8"/></svg></button><button type="button" class="work-tab-close" data-close-tab="${id}" aria-label="Fechar aba ${esc(pageLabel(id))}" title="Fechar aba">×</button></div>`).join('')}</div><button type="button" id="add-work-tab" aria-label="Nova aba" aria-expanded="${tabPickerOpen}" title="Nova aba">＋</button>${tabPickerOpen?`<div class="work-tab-picker" role="dialog" aria-label="Histórico"><div><b>Histórico</b><button type="button" id="close-tab-picker" aria-label="Fechar histórico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>${Object.keys(modules).filter(usesWorkTab).map(id=>`<button type="button" data-open-tab="${id}"><span>${esc(pagePath(id))}</span>${workTabs.includes(id)?'<small>aberta</small>':''}</button>`).join('')}</div>`:''}`;root.querySelectorAll('[data-work-tab]').forEach(b=>{b.onclick=()=>{if(Date.now()>tabDragSuppress)navigate(b.dataset.workTab)};b.onkeydown=e=>{const index=workTabs.indexOf(b.dataset.workTab);if(e.altKey&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveWorkTab(b.dataset.workTab,e.key==='ArrowRight'?1:-1);return}let next;if(e.key==='ArrowRight')next=workTabs[(index+1)%workTabs.length];if(e.key==='ArrowLeft')next=workTabs[(index+workTabs.length-1)%workTabs.length];if(e.key==='Home')next=workTabs[0];if(e.key==='End')next=workTabs.at(-1);if(next){e.preventDefault();navigate(next);root.querySelector(`[data-work-tab="${next}"]`)?.focus()}}});bindWorkTabDrag(root);root.querySelectorAll('[data-pin-tab]').forEach(b=>b.onclick=()=>{const id=b.dataset.pinTab;if(pinnedTabs.includes(id))pinnedTabs=pinnedTabs.filter(x=>x!==id);else pinnedTabs.push(id);workTabs=[...workTabs.filter(x=>pinnedTabs.includes(x)),...workTabs.filter(x=>!pinnedTabs.includes(x))];storeWorkTabs();renderWorkTabs();root.querySelector(`[data-pin-tab="${id}"]`)?.focus()});root.querySelectorAll('[data-close-tab]').forEach(b=>b.onclick=()=>closeWorkTab(b.dataset.closeTab));$('#add-work-tab').onclick=()=>{tabPickerOpen=!tabPickerOpen;renderWorkTabs();if(tabPickerOpen)root.querySelector('[data-open-tab]')?.focus()};if(tabPickerOpen){$('#close-tab-picker').onclick=()=>{tabPickerOpen=false;renderWorkTabs();$('#add-work-tab').focus()};root.querySelectorAll('[data-open-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.openTab))}}
let tabDragSuppress=0;
function moveWorkTab(id,direction){const index=workTabs.indexOf(id),target=workTabs[index+direction];if(!target||pinnedTabs.includes(id)!==pinnedTabs.includes(target))return;[workTabs[index],workTabs[index+direction]]=[target,id];storeWorkTabs();renderWorkTabs();document.querySelector(`[data-work-tab="${id}"]`)?.focus()}
function bindWorkTabDrag(root){root.querySelectorAll('[data-work-tab]').forEach(button=>{let drag=null;const cleanup=()=>{root.querySelectorAll('.tab-drop-before,.tab-drop-after,.tab-dragging').forEach(el=>el.classList.remove('tab-drop-before','tab-drop-after','tab-dragging'));drag=null};button.onpointerdown=e=>{if(e.button!==0)return;drag={id:button.dataset.workTab,pointer:e.pointerId,x:e.clientX,y:e.clientY,started:false,target:null,after:false};button.setPointerCapture(e.pointerId)};button.onpointermove=e=>{if(!drag||drag.pointer!==e.pointerId)return;if(!drag.started&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<7)return;drag.started=true;e.preventDefault();root.querySelectorAll('.tab-drop-before,.tab-drop-after').forEach(el=>el.classList.remove('tab-drop-before','tab-drop-after'));button.closest('.work-tab').classList.add('tab-dragging');const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-tab-id]');drag.target=null;if(target&&target.dataset.tabId!==drag.id&&pinnedTabs.includes(target.dataset.tabId)===pinnedTabs.includes(drag.id)){const rect=target.getBoundingClientRect();drag.target=target.dataset.tabId;drag.after=e.clientX>rect.left+rect.width/2;target.classList.add(drag.after?'tab-drop-after':'tab-drop-before')}const list=root.querySelector('.work-tab-list'),r=list.getBoundingClientRect();if(e.clientX>r.right-30)list.scrollLeft+=12;if(e.clientX<r.left+30)list.scrollLeft-=12};button.onpointerup=e=>{if(!drag)return;const d=drag;cleanup();if(button.hasPointerCapture(e.pointerId))button.releasePointerCapture(e.pointerId);if(!d.started)return;tabDragSuppress=Date.now()+500;if(d.target){workTabs=workTabs.filter(id=>id!==d.id);workTabs.splice(workTabs.indexOf(d.target)+(d.after?1:0),0,d.id);storeWorkTabs();renderWorkTabs()}};button.onpointercancel=cleanup;button.onlostpointercapture=cleanup;button.addEventListener('keydown',e=>{if(e.key==='Escape'&&drag){tabDragSuppress=Date.now()+500;cleanup()}})})}
function closeWorkTab(id){captureTabView();const index=workTabs.indexOf(id);if(index<0)return;workTabs=workTabs.filter(x=>x!==id);pinnedTabs=pinnedTabs.filter(x=>x!==id);delete tabViews[id];if(active===id){const next=workTabs[Math.min(index,workTabs.length-1)]||'painel';active='';navigate(next,{notify:false,tutorial:false})}else{storeWorkTabs();renderWorkTabs()}}
function navigate(id,{notify=true,tutorial=true}={}){if(!modules[id])id='painel';setMobileMenu(false);if(tourActive)finishTour();closeNotifications();const previous=active;if(workTabs.includes(previous))captureTabView();if(usesWorkTab(id)&&!workTabs.includes(id))workTabs.push(id);active=id;tabReady=true;tabPickerOpen=false;restoreTabView(id);if(usesWorkTab(id))prefs.recent=[id,...prefs.recent.filter(x=>x!==id&&usesWorkTab(x))].slice(0,7);persistPrefs();storeWorkTabs();const g=currentGroup();if(g)expanded.add(g[0]);history.replaceState(null,'','#'+id);render();if(id==='painel'){const attention=$('.attention');attention?.classList.add('attention-entry-pulse');if(attention)setTimeout(()=>attention.classList.remove('attention-entry-pulse'),5000);attention?.addEventListener('animationend',()=>attention.classList.remove('attention-entry-pulse'),{once:true})}const view=tabViews[id];if(view?.companyDraft&&$('#company-form'))for(const [name,value]of Object.entries(view.companyDraft)){const input=$('#company-form').elements.namedItem(name);if(input)input.value=value}window.scrollTo(0,view?.scroll||0);if(tutorial&&id!=='recentes'&&!prefs.tours[id])setTimeout(()=>{if(active===id)startTour()},150)}
window.addEventListener('pagehide',captureTabView);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&tabPickerOpen){tabPickerOpen=false;renderWorkTabs();$('#add-work-tab').focus()}});
document.addEventListener('pointerdown',e=>{if(tabPickerOpen&&!e.target.closest('#workspace-tabs')){tabPickerOpen=false;renderWorkTabs()}});
function modulePinButton(id,label){if(id==='painel')return ''; const pinned=prefs.pinnedModules.includes(id);return `<button type="button" class="module-pin" data-pin-module="${id}" aria-label="${pinned?'Desafixar':'Fixar'} módulo ${esc(label)}" aria-pressed="${pinned}" title="${pinned?'Desafixar':'Fixar'} módulo"><svg viewBox="0 0 24 24" fill="${pinned?'currentColor':'none'}" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M8 3h8l-1 7 4 4H5l4-4-1-7M12 14v8"/></svg></button>`}
function toggleModulePin(id){if(id==='painel'||!prefs.order.includes(id))return;const before=[...prefs.pinnedModules],pinned=before.includes(id);prefs.pinnedModules=pinned?before.filter(x=>x!==id):[...before,id];try{persistPrefs()}catch{prefs.pinnedModules=before;toast('Não foi possível salvar a fixação do módulo.');return}render();document.querySelector(`[data-pin-module="${id}"]`)?.focus();}
function navView(){const visible=prefs.order.filter(id=>id!=='recentes'||prefs.showRecent),pinned=visible.filter(id=>!['recentes','kanban','pendentes'].includes(id)&&prefs.pinnedModules.includes(id)),normal=visible.filter(id=>!['painel','recentes','kanban','pendentes'].includes(id)&&!pinned.includes(id));return ['painel','kanban','pendentes',...(prefs.showRecent?['recentes']:[]),...pinned,...normal].map(id=>{const [label,icon,children]=groupDefs[id],items=children,section=id===pinned[0]?'<div class="nav-section-label">Fixados</div>':id===normal[0]?'<div class="nav-section-label">Módulos</div>':'';if(id==='painel')return `<div class="nav-group" data-menu-id="painel"><button class="nav-parent ${active==='painel'?'current':''}" data-nav="painel" ${active==='painel'?'aria-current="page"':''}>${svg(icon)}<span>${label}</span></button></div>`;if(id==='recentes')return `<div class="nav-group" data-menu-id="recentes"><button class="nav-parent ${active==='recentes'?'current':''}" data-nav="recentes" ${active==='recentes'?'aria-current="page"':''}>${svg(icon)}<span>${label}</span></button></div>`;return `${section}<div class="nav-group ${prefs.pinnedModules.includes(id)?'is-pinned':''}" data-menu-id="${id}"><button class="nav-parent ${items.includes(active)&&id!=='recentes'?'current':''}" data-group="${id}" title="${id==='painel'?'Início':'Arraste para reordenar. Alt + seta para mover pelo teclado.'}" ${items.length>1?`aria-expanded="${expanded.has(id)}"`:items.includes(active)?'aria-current="page"':''}>${svg(icon)}<span>${label}</span>${items.length>1?`<span class="chevron">${expanded.has(id)?'−':''}</span>`:''}</button>${modulePinButton(id,label)}${items.length>1&&expanded.has(id)?`<div class="subnav">${items.map(child=>`<button data-nav="${child}" class="${active===child?'active':''}" ${active===child?'aria-current="page"':''}>${pageLabel(child)}</button>`).join('')||'<small class="recent-empty">Seus acessos aparecerão aqui.</small>'}</div>`:''}</div>`}).join('')}
function render(){if(!data)return;renderWorkTabs();$('#nav').innerHTML=navView();$('#company').textContent=data.company.fantasyName;decorateCompanyCopies($('.workspace'));$('#title').textContent=['comercial','ordens'].includes(active)?'Comercial':modules[active][0];renderBreadcrumb();$('#billing-pdf').hidden=active!=='faturamento';const group=currentGroup();$('#administration').classList.toggle('active',active==='configuracoes');const children=group?.[1][2]||[];$('#context-tabs').innerHTML=children.length>1?`<div class="context-tabs" aria-label="Subpáginas">${children.map(id=>`<button data-nav="${id}" class="${active===id?'selected':''}">${pageLabel(id)}</button>`).join('')}</div>`:'';const labels={templates:'Novo modelo',painel:'Novo orçamento',clientes:'Novo cliente',comercial:'Novo orçamento',pendentes:'Novo orçamento',ordens:'Emitir ordem',agenda:'Novo compromisso'};$('#new').hidden=!labels[active];$('#new').textContent=labels[active]||'';const views={recentes:recentView,painel:dashboard,indicadores:indicators,clientes:clients,comercial:commercial,pendentes:approvalView,ordens:orderView,kanban:kanban,entregas:orderView,contratos:contracts,faturamento:financeView,agenda:agenda,configuracoes:settings,templates:templateView};$('#content').innerHTML=views[active]();bind();decorateNavigation();decorateProtocols($('#content'));renderNotifications()}
function pageLabel(id){return {clientes:'Clientes',indicadores:'Indicadores',contratos:'Arquivo de documentos',faturamento:'Faturamento',agenda:'Agenda',configuracoes:'Administração',pendentes:'Aprovações'}[id]||modules[id]?.[0]||id}
function pagePath(id){const group=Object.values(groupDefs).find(g=>g[2].includes(id)),labels=[group?.[0],pageLabel(id)].filter(Boolean);return labels.filter((label,i)=>i===0||label.toLocaleLowerCase('pt-BR')!==labels[i-1].toLocaleLowerCase('pt-BR')).join(' > ')}
function recentView(){const list=prefs.recent.filter(id=>usesWorkTab(id)&&(!query||matchesSearch([pagePath(id)])));return `<section class="recent-panel" aria-label="Acessos recentes"><div class="recent-pages">${list.map((id,i)=>`<button class="recent-page recent-card" data-nav="${id}" data-accent="${i%4}"><span class="recent-card-top"><span class="recent-page-icon">${svg(Object.values(groupDefs).find(g=>g[2].includes(id))?.[1]||'painel')}</span><span class="recent-card-arrow" aria-hidden="true">↗</span></span><span class="recent-card-body"><b>${esc(pageLabel(id))}</b><small class="recent-path">${esc(pagePath(id))}</small></span></button>`).join('')||'<p class="empty">Nenhum acesso encontrado.</p>'}</div></section>`}


function kpiCards(items){return `<div class="overview-kpis">${items.map(([l,v,n,id,color='blue'])=>`<button class="overview-kpi ${color}" data-nav="${id}"><span>${l}</span><strong>${v}</strong><small>${n}</small><span class="kpi-arrow">→</span></button>`).join('')}</div>`}
function dashboard(){const f=financials(),ready=data.proposals.filter(p=>approval(p)&&!p.projectCode),orders=data.proposals.filter(p=>p.projectCode&&p.erpStage!=='Concluído');return kpiCards([['Orçamentos pendentes',data.proposals.filter(p=>isAwaitingApproval(p)).length,'aguardando aprovação','pendentes'],['Projetos em andamento',orders.length,'ordens não concluídas','kanban','purple'],['Aguardando emissão',ready.length,'orçamentos aprovados','ordens','orange'],['Saldo pendente',money(f.balance),'sobre o valor contratado','faturamento','green']])+`<section class="launchpad"><h2>Acesso rápido</h2><div class="app-tiles">${[['clientes','clientes','Clientes','dados para os orçamentos'],['comercial','comercial','Comercial','consulta e emissão'],['indicadores','indicadores','Indicadores','gráficos e critérios de cálculo'],['faturamento','faturamento','Faturamento','parcelas e comprovantes']].map(([id,icon,t,n],i)=>`${i===0?'<div class="primary-tiles">':''}<button class="app-tile" data-nav="${id}">${svg(icon)}<span><b>${t}</b><small>${n}</small></span><span class="tile-arrow">›</span></button>${i===2?'</div>':''}`).join('')}</div></section><div class="work-grid"><section class="panel"><div class="panel-head"><div><h2>Monitor de projetos</h2><p>Selecione uma linha para consultar o orçamento.</p></div><button class="text-link" data-nav="comercial">Abrir carteira →</button></div>${proposalTable(filtered().slice(0,5))}</section><section class="panel attention"><div class="panel-head"><h2>Requer atenção</h2></div>${[[orders.filter(p=>p.deliveryDate<today()).length,'Projetos com prazo vencido','confira o andamento das entregas','ordens'],[ready.length,'Orçamentos aguardando ordem','revise o escopo antes da emissão','ordens'],[f.overdue.length,'Parcelas vencidas','consulte os saldos no faturamento','faturamento']].map(([n,t,note,id])=>`<button class="attention-row" data-nav="${id}"><span class="attention-number">${n}</span><span><b>${t}</b></span><span>›</span></button>`).join('')}</section></div>`}
function proposalTable(p){return `<div class="table-wrap"><table><thead><tr><th>Protocolo</th><th>Cliente</th><th>Valor</th><th>Situação</th></tr></thead><tbody>${p.map(x=>`<tr class="selectable ${selected===x.code?'row-selected':''}" data-select="${esc(x.code)}" tabindex="0" aria-label="Selecionar ${approval(x)?'projeto':'orçamento'} ${esc(displayProtocol(x))}"><td><b>${esc(x.campaign)}</b><small>${esc(displayProtocol(x))}</small>${selected===x.code?`<div class="row-actions"><button class="text-link" data-detail="${esc(x.code)}">Detalhar</button><button class="text-link" data-edit="${esc(x.code)}">Editar orçamento</button>${isAwaitingApproval(x)?`<button class="text-link" data-approval-open="${esc(x.code)}">Analisar aprovação</button>`:''}${approval(x)&&!x.projectCode?`<button class="text-link" data-issue="${esc(x.code)}">Emitir ordem de serviço</button>`:''}</div>`:''}</td><td>${esc(x.client)}<small>${esc(x.responsible)}</small></td><td class="numeric">${money(x.netValue)}</td><td>${badge(x.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nenhum orçamento encontrado.</td></tr>'}</tbody></table></div>`}
function filters(){return `<div class="filter-bar"><label>Cliente<select id="filter-client"><option value="">Todos os clientes</option>${data.clients.map(c=>`<option value="${c.code}" ${String(c.code)===clientFilter?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Situação<select id="filter-status">${['Todos','Em negociação','Enviado','Aprovado','Recusado','Cancelado'].map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select></label><label>Ordenação<select id="filter-sort">${[['recent','Protocolo decrescente'],['value','Maior valor'],['client','Cliente de A a Z']].map(([v,l])=>`<option value="${v}" ${v===sortOrder?'selected':''}>${l}</option>`).join('')}</select></label><button class="button secondary" id="reset-filters">Limpar filtros</button></div>`}
function commercial(){const p=filtered().filter(p=>active!=='pendentes'||isAwaitingApproval(p));return `<section class="panel list-report">${filters()}<div class="panel-head table-toolbar"><h2>${modules[active][0]} <span class="heading-count">${p.length}</span></h2><span class="toolbar-note">Clique no orçamento para exibir as ações.</span></div>${proposalTable(p)}<div class="panel-foot"><span>${p.length} registros</span><span>valores em BRL</span></div></section>`}

function isAwaitingApproval(p){return ['Em negociação','Enviado'].includes(p.status)&&!p.projectCode&&!(p.receivedValue>0)}
function openApproval(code){navigate('pendentes',{tutorial:false});selected=code;render();captureTabView()}
function approvalView(){const queue=filtered().filter(isAwaitingApproval),p=data.proposals.find(p=>p.code===selected)||queue[0];return `<div class="approval-workflow"><section class="panel"><div class="panel-head"><h2>Pendentes de aprovação <span class="heading-count">${queue.length}</span></h2></div><p class="approval-note">Orçamentos em negociação ou enviados. A aprovação confirma o comercial; a ordem de serviço libera a execução em uma etapa separada.</p><div class="approval-queue">${queue.map(x=>`<button class="approval-item ${p?.code===x.code?'selected':''}" data-approval-select="${esc(x.code)}"><b>${esc(x.campaign)}</b><span>${esc(x.client)}</span><small>${esc(displayProtocol(x))} · ${money(x.netValue)}</small>${badge(x.status)}</button>`).join('')||'<p class="empty">Nenhum orçamento pendente nos filtros atuais. Os aprovados estão em Projetos e ordens.</p>'}</div><button class="text-link" data-nav="comercial">Ver todos os orçamentos</button></section><section class="panel approval-analysis"><div class="panel-head"><h2>Análise e decisão comercial</h2></div>${p?approvalAnalysis(p):'<p class="empty">Selecione um orçamento pendente para analisar e registrar a decisão.</p>'}</section></div>`}
function approvalAnalysis(p){const c=data.clients.find(c=>String(c.code)===String(p.clientCode)),history=p.approvalHistory||[];return `<div class="approval-body"><div class="detail-title"><h3>${esc(p.campaign)}</h3>${badge(p.status)}</div>${readonlyClient(c)}<dl class="detail-grid">${[['Protocolo',displayProtocol(p)],['Valor do orçamento',money(p.netValue)],['Responsável comercial',p.responsible],['Captação',day(p.captureDate)],['Entrega',day(p.deliveryDate)],['Local',p.location||'Não informado'],['Escopo',p.scopeItems||'Não informado'],['Pagamento',p.paymentMethod||'Não informado'],['Modelo de contrato',p.contractTemplate?.name||'Ainda não selecionado']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Não informado')}</dd></div>`).join('')}</dl><div class="approval-actions">${isAwaitingApproval(p)?`<button class="button primary" data-approval-decision="Aprovado" data-code="${esc(p.code)}">Registrar aprovação</button><button class="button secondary" data-approval-decision="Recusado" data-code="${esc(p.code)}">Registrar recusa</button><button class="button secondary" data-approval-decision="Em negociação" data-code="${esc(p.code)}">Registrar situação: Em negociação</button><button class="text-link" data-edit="${esc(p.code)}">Editar orçamento</button>`:approval(p)?`<p>Comercial aprovado. ${p.projectCode?'A ordem já foi emitida.':'A execução ainda depende da emissão da ordem de serviço.'}</p>${!p.projectCode?`<button class="button primary" data-issue="${esc(p.code)}">Emitir ordem de serviço</button>`:''}<button class="text-link" data-nav="ordens">Ver projetos e ordens</button>`:'<p>Este orçamento não está na fila de aprovação. O registro e seus documentos permanecem disponíveis em Comercial.</p>'}</div><h3>Histórico de decisões</h3>${history.length?`<ol class="approval-history">${[...history].reverse().map(h=>`<li><b>${esc(h.toStatus)}</b><small>${day(h.at.slice(0,10))} · ${esc(h.actor)} · origem: ${esc(h.fromStatus)}</small><p>${esc(h.note||'Sem observações adicionais.')}</p></li>`).join('')}</ol>`:`<p class="approval-note">Sem decisão registrada nesta tela. Situação atual: ${esc(p.status)}. Registros anteriores foram preservados sem inventar data ou autor de aprovação.</p>`}</div>`}
function openApprovalDecision(code,status){const p=data.proposals.find(p=>p.code===code);if(!p||!isAwaitingApproval(p))return;editing=code;showModal('approval','Registrar decisão comercial',`<div class="info-strip">${esc(p.campaign)} · ${money(p.netValue)}<br>Esta ação salva a situação do orçamento e permanece em Aprovações. Não abre outro módulo, emite ordem ou registra pagamento.</div>`+selectField('decision','Decisão',['Aprovado','Recusado','Em negociação'].map(x=>[x,x]),status,'required')+field('decisionActor','Quem comunicou ou confirmou a decisão','','text','required maxlength="160"')+`<label class="full-width">Observação / referência da confirmação<textarea name="decisionNote" rows="4" maxlength="4000" placeholder="Ex.: confirmação por e-mail, ajustes solicitados ou motivo da recusa"></textarea></label>`,'Salvar decisão')}
function recordApprovalDecision(p,v){if(!p||!isAwaitingApproval(p))throw Error('Este orçamento não está mais pendente de aprovação.');if(!['Aprovado','Recusado','Em negociação'].includes(v.decision))throw Error('Decisão inválida.');if(!v.decisionActor?.trim())throw Error('Identifique quem confirmou a decisão.');if(v.decision!=='Aprovado'&&!v.decisionNote?.trim())throw Error('Informe o motivo ou os ajustes solicitados.');(p.approvalHistory??=[]).push({id:crypto.randomUUID(),at:new Date().toISOString(),fromStatus:p.status,toStatus:v.decision,actor:v.decisionActor.trim(),note:v.decisionNote||''});p.status=v.decision}

function clients(){const list=data.clients.filter(c=>matchesSearch([c.name,c.legalName,c.cnpj,c.code,c.contact,c.address]));return `<section class="panel"><div class="object-intro"><div class="intro-icon">${svg('clientes')}</div><div><h2>Clientes</h2><p>O código é único e sequencial, começando em 100.</p></div><div class="intro-total"><strong>${data.clients.length}</strong><span>clientes cadastrados</span></div></div><div class="table-wrap"><table><thead><tr><th>Código / cliente</th><th>CNPJ</th><th>Contato</th><th>Localização</th><th>Ação</th></tr></thead><tbody>${list.map(c=>`<tr><td><b>${esc(c.code)} · ${esc(c.name)}</b><small>${esc(c.legalName)}</small></td><td>${esc(c.cnpj)}</td><td>${esc(c.contact)}</td><td>${esc(c.address)}</td><td><button class="text-link" data-client="${c.code}">Consultar</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum cliente encontrado.</td></tr>'}</tbody></table></div></section>`}
function orderView(){const issued=filtered().filter(p=>p.projectCode&&(active!=='entregas'||p.erpStage==='Concluído')),ready=filtered().filter(p=>approval(p)&&!p.projectCode);return (active==='ordens'?`<section class="panel ready"><div class="panel-head"><div><h2>Aguardando emissão <span class="heading-count">${ready.length}</span></h2><p>Confirme os dados do projeto antes de liberar a execução.</p></div></div>${ready.map(p=>`<div class="ready-row"><div><b>${esc(p.campaign)}</b><p>${esc(p.client)} · ${esc(displayProtocol(p))}</p></div><button class="button secondary" data-issue="${esc(p.code)}">Emitir ordem de serviço</button></div>`).join('')||'<p class="empty">Nenhum orçamento aguardando emissão.</p>'}</section>`:'')+`<section class="panel"><div class="panel-head"><h2>${active==='entregas'?'Projetos concluídos':'Ordens emitidas'} <span class="heading-count">${issued.length}</span></h2></div><div class="table-wrap"><table><thead><tr><th>Projeto / protocolo</th><th>Responsável</th><th>Entrega</th><th>Etapa</th><th>Ação</th></tr></thead><tbody>${issued.map(p=>`<tr><td><b>${esc(p.campaign)}</b><small>${esc(displayProtocol(p))}</small></td><td>${esc(p.responsible)}</td><td>${day(p.deliveryDate)}</td><td>${badge(p.erpStage||stages[0])}</td><td><button class="text-link" data-detail="${esc(p.code)}">Consultar</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum projeto encontrado.</td></tr>'}</tbody></table></div></section>`}
let kanbanSearch={},kanbanFacetFilters={};
function projectSearchText(p){const values=[];function visit(value,key=''){if(['content','snapshotCompany'].includes(key))return;if(Array.isArray(value)){value.forEach(v=>visit(v));return}if(value&&typeof value==='object'){Object.entries(value).forEach(([k,v])=>visit(v,k));return}if(value!=null){values.push(String(value));if(typeof value==='number')values.push(money(value));if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value))values.push(day(value))}}visit(p);visit(data.clients.find(c=>String(c.code)===String(p.clientCode)));values.push(displayProtocol(p));return searchText(values.join(' '))}
function filterKanbanColumn(stage){const column=Array.from(document.querySelectorAll('[data-drop-stage]')).find(c=>c.dataset.dropStage===stage);if(!column)return;const term=searchText(kanbanSearch[stage]||''),cards=[...column.querySelectorAll('.kanban-card')];let visible=0;cards.forEach(card=>{const p=data.proposals.find(p=>p.code===card.dataset.dragCode);const facet=kanbanFacetFilters[stage]||{};card.hidden=!!term&&!projectSearchText(p).includes(term)||!!facet.client&&String(p.clientCode)!==facet.client||!!facet.attachments&&(Boolean(p.documents?.length||p.receipts?.some(r=>r.attachment))!==(facet.attachments==='yes'));if(!card.hidden)visible++});column.querySelector('.column-count').textContent=term?`${visible} / ${cards.length}`:String(cards.length);column.querySelector('.column-empty').hidden=visible>0;let chips=column.querySelector('.kanban-filter-tags');if(!chips){chips=document.createElement('div');chips.className='kanban-filter-tags active-filter-tags';column.querySelector('h3').after(chips)}chips.replaceChildren();const facets=kanbanFacetFilters[stage]||{},tags=[...(term?[['text',kanbanSearch[stage]]]:[]),...(facets.client?[['client',data.clients.find(c=>String(c.code)===facets.client)?.name||facets.client]]:[]),...(facets.attachments?[['attachments',facets.attachments==='yes'?'Com anexos':'Sem anexos']]:[])];tags.forEach(([key,label])=>{const token=document.createElement('span');token.className='search-token';const text=document.createElement('span');text.textContent=label;const x=document.createElement('button');x.type='button';x.setAttribute('aria-label','Remover filtro '+label);x.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m7 7 10 10M17 7 7 17"/></svg>';x.onclick=()=>{if(key==='text'){kanbanSearch[stage]='';column.querySelector('[data-column-search]').value=''}else delete kanbanFacetFilters[stage][key];filterKanbanColumn(stage)};token.append(text,x);chips.append(token)});chips.hidden=!tags.length}
function bindKanbanSearch(){document.querySelectorAll('[data-column-search]').forEach(input=>{input.oninput=()=>{kanbanSearch[input.dataset.columnSearch]=input.value;filterKanbanColumn(input.dataset.columnSearch)};input.onkeydown=e=>{if(e.key==='Escape'){input.value='';kanbanSearch[input.dataset.columnSearch]='';filterKanbanColumn(input.dataset.columnSearch)}};filterKanbanColumn(input.dataset.columnSearch)})}
function kanban(){return `<div class="board" role="list" aria-label="Quadro de projetos">${stages.map(s=>{const projects=filtered().filter(p=>p.projectCode&&(p.erpStage||stages[0])===s);return `<section class="column" data-drop-stage="${esc(s)}" aria-label="${esc(s)}"><h3>${s}<span class="column-count">${projects.length}</span></h3><label class="column-search"><span aria-hidden="true">⌕</span><input type="search" data-column-search="${esc(s)}" aria-label="Pesquisar em ${esc(s)}" placeholder="Pesquisar nesta coluna" value="${esc(kanbanSearch[s]||'')}"></label>${projects.map(p=>`<article class="kanban-card" data-drag-code="${esc(p.code)}" tabindex="0" aria-roledescription="cartão arrastável" aria-label="Mover projeto ${esc(p.campaign)}" title="Arraste para outra coluna. Pelo teclado, use espaço, setas e Enter."><div class="card-reference"><small class="reference">${esc(displayProtocol(p))}</small><span class="drag-handle" aria-hidden="true">⠿</span></div><h3>${esc(p.campaign)}</h3><p class="card-customer">${esc(p.client)}</p><div class="card-facts"><div><small>Entrega</small><strong>${day(p.deliveryDate)}</strong></div><div><small>Valor contratado</small><strong>${money(p.netValue)}</strong></div></div><button class="text-link" data-detail="${esc(p.code)}">Consultar projeto</button></article>`).join('')}<p class="column-empty" hidden>Nenhum projeto encontrado.</p></section>`}).join('')}</div>`}

function contracts(){const list=filtered().filter(approval);return `<section class="panel"><div class="panel-head"><div><h2>Arquivo de contratos</h2><p>Documentos organizados por orçamento e cliente.</p></div></div><div class="table-wrap"><table><thead><tr><th>Contrato / cliente</th><th>Protocolo</th><th>Documentos</th><th>Ação</th></tr></thead><tbody>${list.map(p=>`<tr><td><b>${esc(p.campaign)}</b><small>${esc(p.client)} · ${money(p.netValue)}</small></td><td>${esc(displayProtocol(p))}</td><td>${contractDocumentRows(p)}</td><td><button class="text-link contract-generate-link" data-contract-generate="${esc(p.code)}">Gerar contrato</button><button class="text-link" data-document="${esc(p.code)}">Anexar contrato</button><button class="text-link document-link" data-detail="${esc(p.code)}">Consultar dados</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nenhum contrato disponível.</td></tr>'}</tbody></table></div></section>`}
function financeKpis(list){const f=financials(list);return `<div class="financial-kpis">${[['Valor contratado',money(f.contracted),'total dos orçamentos aprovados'],['Valor faturado',money(f.billed),'soma das parcelas emitidas'],['Valor recebido',money(f.received),'entradas e saldos históricos'],['Saldo pendente',money(f.balance),'contratado menos recebido'],['Parcelas a vencer',money(sum(f.upcoming,'balance')),`${f.upcoming.length} parcelas com vencimento hoje ou depois`],['Parcelas vencidas',money(sum(f.overdue,'balance')),`${f.overdue.length} parcelas com saldo e data anterior a hoje`]].map(([l,v,n],i)=>`<article class="metric ${i===5?'late-metric':''}"><div class="metric-label">${l}<button type="button" class="finance-info" data-finance-info="${i}" aria-label="Entender ${l}" title="Entender ${l}">i</button></div><div class="metric-value">${v}</div><div class="metric-note">${n}</div></article>`).join('')}</div>`}
function financeView(){const p=filtered().filter(approval);return financeKpis(p)+`<section class="panel"><div class="panel-head"><div><h2>Contratos e recebíveis</h2><p>Defina as parcelas e registre cada recebimento com comprovante ou dispensa explícita.</p></div></div><div class="table-wrap"><table><thead><tr><th>Cliente / contrato</th><th>Protocolo</th><th>Recebido / saldo</th><th>Faturamento</th><th>Ações</th></tr></thead><tbody>${p.map(p=>`<tr><td><b>${esc(p.client)}</b><small>${esc(p.campaign)}</small></td><td>${esc(displayProtocol(p))}</td><td><b>${money(p.receivedValue)}</b><small>saldo ${money(p.netValue-p.receivedValue)}</small></td><td><b>${money(sum(p.invoices||[],'amount'))}</b><small>${(p.invoices||[]).length} parcelas emitidas</small></td><td><button class="text-link" data-billing="${esc(p.code)}">Detalhar faturamento</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum recebível encontrado.</td></tr>'}</tbody></table></div></section>`}
function indicators(){const list=filtered(),approved=list.filter(approval),f=financials(list),conversion=Math.round(approved.length/(list.length||1)*100),orders=list.filter(p=>p.projectCode),done=orders.filter(p=>p.erpStage==='Concluído');return `<div class="panel analytics-scope"><label>Data inicial<input id="analytics-from" type="date" value="${esc(analyticsFrom)}"></label><label>Data final<input id="analytics-to" type="date" value="${esc(analyticsTo)}"></label><button class="button primary" id="analytics-apply">Aplicar período</button><button class="button secondary" id="analytics-reset">Todo o histórico</button></div>`+`<div class="analytics-period-shortcuts" aria-label="Períodos de análise">${[[1,'1 mês'],[3,'3 meses'],[6,'6 meses'],[12,'1 ano']].map(([n,l])=>`<button class="button secondary" data-analysis-months="${n}">${l}</button>`).join('')}<span>${analyticsFrom?day(analyticsFrom)+' a '+day(analyticsTo):'Todo o histórico'}</span></div>`+financeKpis(list)+`<div class="analytics-grid">${trendChart(list)}${statusChart(list)}</div><div class="analytics-grid"><section class="panel"><div class="panel-head"><h2>Etapas dos projetos</h2></div><div class="horizontal-bars">${stages.map(s=>{const n=orders.filter(p=>(p.erpStage||stages[0])===s).length;return `<div><span>${s}</span><div><i style="width:${n/(orders.length||1)*100}%"></i></div><b>${n}</b></div>`}).join('')}</div><div class="panel-foot">Base: ${orders.length} projetos com ordem emitida.</div></section><section class="panel"><div class="panel-head"><h2>Resumo executivo</h2></div><dl class="executive-summary"><div><dt>Conversão em aprovação</dt><dd>${conversion}%</dd></div><div><dt>Ticket médio aprovado</dt><dd>${money(f.contracted/(approved.length||1))}</dd></div><div><dt>Projetos concluídos</dt><dd>${done.length} de ${orders.length}</dd></div><div><dt>Recebimento sobre o contratado</dt><dd>${f.contracted?Math.round(f.received/f.contracted*100):0}%</dd></div><div><dt>Orçamentos no período</dt><dd>${list.length}</dd></div></dl></section></div>`}
function trendChart(list){const grouped={};for(const p of list){const key=emissionDate(p).slice(0,7);if(!key)continue;grouped[key]??={total:0,received:0};grouped[key].total+=p.netValue;grouped[key].received+=p.receivedValue}const months=Object.keys(grouped).sort().slice(-12),max=Math.max(1,...months.map(m=>grouped[m].total));return `<section class="panel"><div class="panel-head"><div><h2>Evolução dos orçamentos</h2><p>Até 12 meses com registros, agrupados pela emissão.</p></div></div><div class="legend"><span><i class="dot"></i>valor emitido</span><span><i class="dot light"></i>recebido acumulado</span></div><div class="chart"><div class="axis"><span>${money(max)}</span><span>${money(max*.5)}</span><span>0</span></div><div class="bars">${months.map(m=>`<div class="bar-group"><div class="bar" style="height:${grouped[m].total/max*95}%" title="${m}: ${money(grouped[m].total)}"></div><div class="bar pale" style="height:${grouped[m].received/max*95}%" title="Recebido: ${money(grouped[m].received)}"></div><span class="bar-label">${m.slice(5)}/${m.slice(2,4)}</span></div>`).join('')||'<p>Sem dados no período.</p>'}</div></div></section>`}
function statusChart(list){const statuses=['Em negociação','Enviado','Aprovado','Recusado','Cancelado'],colors=['#9877c8','#6994c9','#468d77','#c17272','#acb7c7'];let offset=0;const segments=statuses.map((s,i)=>{const start=offset;offset+=list.filter(p=>p.status===s).length/(list.length||1)*100;return `${colors[i]} ${start}% ${offset}%`});return `<section class="panel"><div class="panel-head"><div><h2>Situação comercial</h2><p>Quantidade de orçamentos em cada situação.</p></div></div><div class="pipeline"><div class="donut" style="background:${list.length?'conic-gradient('+segments.join(',')+')':'#e3e9f1'}"><div>${list.length}<small>orçamentos</small></div></div><div class="pipeline-legend">${statuses.map((s,i)=>`<div class="pipeline-row"><span><i class="dot" style="background:${colors[i]}"></i>${s}</span><b>${list.filter(p=>p.status===s).length}</b></div>`).join('')}</div></div></section>`}
let agendaMode='calendar',agendaMonths=1,agendaCursor=today().slice(0,7);
function calendarMonths(base,count){const [year,month]=base.split('-').map(Number);return Array.from({length:count},(_,i)=>new Date(year,month-1+i,1))}
function agendaCalendar(events){return `<div class="calendar-months">${calendarMonths(agendaCursor,agendaMonths).map(month=>{const year=month.getFullYear(),m=month.getMonth(),offset=(new Date(year,m,1).getDay()+6)%7,days=new Date(year,m+1,0).getDate();return `<section class="panel calendar-month"><h2>${esc(month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))}</h2><div class="calendar-weekdays">${['seg','ter','qua','qui','sex','sáb','dom'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days">${Array.from({length:offset},()=>'<div class="calendar-blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const date=year+'-'+String(m+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0'),items=events.filter(e=>e.date===date);return `<div class="calendar-day ${date===today()?'is-today':''}"><time datetime="${date}">${i+1}</time>${items.map(e=>`<button type="button" data-calendar-event="${esc(e.id)}" title="${esc(e.title)}"><small>${esc(e.time)}</small><span>${esc(e.title)}</span></button>`).join('')}</div>`}).join('')}</div></section>`}).join('')}</div>`}
function agenda(){const ev=data.events.filter(e=>(!searchTags.find(t=>t.key==='from')||e.date>=searchTags.find(t=>t.key==='from').value)&&(!searchTags.find(t=>t.key==='to')||e.date<=searchTags.find(t=>t.key==='to').value)&&matchesSearch([e.title,e.location,e.date,day(e.date),e.time,e.projectCode])).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const toolbar=`<div class="panel calendar-toolbar"><div class="calendar-view-buttons"><button class="button ${agendaMode==='calendar'?'primary':'secondary'}" data-agenda-view="calendar">Calendário</button><button class="button ${agendaMode==='list'?'primary':'secondary'}" data-agenda-view="list">Lista</button></div><label>Período<select id="agenda-months">${[[1,'1 mês'],[3,'3 meses'],[6,'6 meses'],[12,'1 ano']].map(([n,l])=>`<option value="${n}" ${agendaMonths===n?'selected':''}>${l}</option>`).join('')}</select></label><label>Começar em<input id="agenda-month" type="month" value="${agendaCursor}"></label><button class="button secondary" data-calendar-shift="-1" aria-label="Período anterior">‹</button><button class="button secondary" id="calendar-today">Hoje</button><button class="button secondary" data-calendar-shift="1" aria-label="Próximo período">›</button></div>`;const months=calendarMonths(agendaCursor,agendaMonths),start=months[0],end=new Date(months.at(-1).getFullYear(),months.at(-1).getMonth()+1,1),visible=ev.filter(e=>{const date=new Date(e.date+'T12:00:00');return date>=start&&date<end});return toolbar+(agendaMode==='calendar'?agendaCalendar(visible):`<section class="panel"><div class="panel-head"><h2>Compromissos cadastrados</h2></div><div class="activity">${visible.map(e=>`<div class="activity-item"><span class="activity-icon">${svg('agenda')}</span><div><b>${esc(e.title)}</b><p>${esc(e.location)}</p><small>${day(e.date)} às ${esc(e.time)}${e.projectCode?' · projeto '+esc(e.projectCode):''}</small></div></div>`).join('')||'<p class="empty">Nenhum compromisso no período selecionado.</p>'}</div></section>`)}

function settings(){const c=data.company,fields=(items)=>items.map(([k,l,type='text',extra=''])=>field(k,l,c[k]||'',type,extra)).join('');return `<section class="panel organization"><div class="organization-head"><span class="organization-avatar">${esc(initials(c.fantasyName))}</span><div><h2>${esc(c.fantasyName)}</h2><p>${esc(c.legalName)}</p></div></div><form id="company-form" class="organization-form"><fieldset><legend>Identificação e contatos</legend><div class="form-grid">${fields([['fantasyName','Nome fantasia','text','required'],['legalName','Razão social','text','required'],['cnpj','CNPJ','text','required'],['contacts','Contato da empresa'],['email','E-mail','email'],['phone','Telefone']])}</div></fieldset><fieldset class="fiscal-fields"><legend>Dados fiscais</legend><div class="form-grid">${fields([['stateRegistration','Inscrição estadual'],['municipalRegistration','Inscrição municipal']])}${selectField('taxRegime','Regime tributário',[['','Selecionar'],['simples','Simples Nacional'],['presumido','Lucro presumido'],['real','Lucro real'],['mei','MEI']],c.taxRegime||'')}${fields([['cnae','CNAE principal'],['municipalCode','Código do município (IBGE)'],['fiscalEmail','E-mail para documentos fiscais','email']])}</div></fieldset><fieldset><legend>Endereço fiscal</legend><div class="form-grid">${fields([['address','Logradouro','text','required'],['addressNumber','Número'],['addressComplement','Complemento'],['district','Bairro'],['city','Município'],['state','UF','text','minlength="2" maxlength="2" pattern="[A-Za-z]{2}"'],['postalCode','CEP']])}</div></fieldset><div class="organization-actions"><button class="button primary">Salvar alterações</button></div></form></section>`}

function readonlyClient(c){return `<div class="client-identity"><h3>Dados do cliente cadastrado</h3><div class="identity-grid">${[['Código',c?.code],['Razão social',c?.legalName],['CNPJ',c?.cnpj],['Contato',c?.contact],['Endereço',c?.address]].map(([l,v])=>`<div><small>${l}</small><b>${esc(v??'selecione um cliente')}</b></div>`).join('')}</div></div>`}
function openProposal(code){editing=code||null;const p=data.proposals.find(p=>p.code===code)||{},locked=!!p.projectCode||p.receivedValue>0,c=data.clients.find(c=>c.code===p.clientCode);if(!data.clients.length){toast('Cadastre um cliente antes de emitir um orçamento.');navigate('clientes');return}
showModal('proposal',code?'Editar orçamento':'Novo orçamento',`<div class="info-strip">${code?'Protocolo '+esc(displayProtocol(p)):'O orçamento recebe ORC e o projeto mantém a mesma numeração com o prefixo PJT.'}${locked?'<br>Cliente, valor e situação estão protegidos por ordem ou recebimento.':''}</div><div class="client-combobox"><label>Cliente<input id="client-search" name="clientSearch" autocomplete="off" value="${esc(c?.name||'')}" placeholder="Digite o nome do cliente" required ${locked?'readonly':''}></label><input type="hidden" name="clientCode" value="${c?.code??''}"><div id="client-suggestions" role="listbox" aria-label="Clientes encontrados" hidden></div></div><div id="client-identity">${readonlyClient(c)}</div>`+contractTemplateField(p)+field('campaign','Nome do projeto',p.campaign||'','text','required')+field('netValue','Valor do orçamento (R$)',p.netValue??'','number',`required min="0.01" max="999999999" step="0.01" ${locked?'readonly':''}`)+selectField('status','Situação',['Em negociação','Enviado','Aprovado','Recusado','Cancelado'].map(s=>[s,s]),p.status||'Em negociação',locked?'disabled':'required')+field('responsible','Responsável',p.responsible||'','text','required')+field('captureDate','Data de captação',p.captureDate||'','date')+field('deliveryDate','Prazo de entrega',p.deliveryDate||'','date')+field('location','Local',p.location||'')+field('scopeItems','Escopo',p.scopeItems||'')+field('teamSize','Quantidade de pessoas',p.teamSize||1,'number','min="1" max="999"')+selectField('priority','Prioridade',['Normal','Alta','Urgente'].map(x=>[x,x]),p.priority||'Normal')+selectField('paymentMethod','Forma de pagamento',['Pix','Transferência','Boleto','Cartão','Outro'].map(x=>[x,x]),p.paymentMethod||'Pix')+field('competencia','Competência',p.competencia||''));
const input=$('#client-search');input.oninput=()=>{const term=input.value.trim().toLowerCase();$('#fields [name="clientCode"]').value='';$('#client-identity').innerHTML=readonlyClient(null);const matches=data.clients.filter(c=>c.name.toLowerCase().includes(term)||c.legalName.toLowerCase().includes(term)).slice(0,8);const exact=matches.filter(c=>c.name.toLowerCase()===term);if(exact.length===1){chooseClient(exact[0]);return}$('#client-suggestions').hidden=!term;$('#client-suggestions').innerHTML=matches.map(c=>`<button type="button" data-suggestion="${c.code}" role="option"><b>${esc(c.name)}</b><small>código ${c.code} · ${esc(c.cnpj)} · ${data.proposals.filter(p=>p.clientCode===c.code).length} orçamentos</small></button>`).join('')||'<p>Nenhum cliente encontrado. Cadastre o cliente no módulo Clientes.</p>';document.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>chooseClient(data.clients.find(c=>String(c.code)===b.dataset.suggestion)))};
}
function chooseClient(c){$('#client-search').value=c.name;$('#fields [name="clientCode"]').value=c.code;$('#client-identity').innerHTML=readonlyClient(c);$('#client-suggestions').hidden=true}
function openClient(){editing=null;showModal('client','Novo cliente',`<div class="info-strip">Próximo código: ${Math.max(99,...data.clients.map(c=>Number(c.code)||99))+1}. O CNPJ identifica o cadastro e não pode se repetir.</div>`+[['name','Nome fantasia'],['legalName','Razão social'],['cnpj','CNPJ'],['contact','Contato'],['address','Endereço']].map(([n,l])=>field(n,l,'','text','required')).join(''))}
function issue(code){const p=data.proposals.find(p=>p.code===code);if(!p||!approval(p)||p.projectCode){toast('Selecione um orçamento aprovado sem ordem.');return}editing=code;showModal('order','Emitir ordem de serviço',`<div class="info-strip">Projeto ${esc(displayProtocol(p))}<br>${esc(p.campaign)} · ${esc(p.client)}</div>`+field('responsible','Responsável',p.responsible,'text','required')+field('captureDate','Início',p.captureDate||'','date','required')+field('deliveryDate','Entrega',p.deliveryDate||'','date','required')+field('scopeItems','Escopo da execução',p.scopeItems||'','text','required')+field('location','Local',p.location||'','text','required'),'Emitir ordem')}
function detail(code){const p=data.proposals.find(p=>p.code===code);editing=code;const c=data.clients.find(c=>c.code===p.clientCode);showModal('readonly','Detalhes do orçamento',`<div class="detail-title"><h3>${esc(p.campaign)}</h3>${badge(p.status)}</div>${readonlyClient(c)}<dl class="detail-grid">${[['Protocolo',displayProtocol(p)],['Valor contratado',money(p.netValue)],['Recebido',money(p.receivedValue)],['Responsável',p.responsible],['Etapa',p.erpStage||'sem execução iniciada'],['Data de captação',day(p.captureDate)],['Entrega',day(p.deliveryDate)],['Local',p.location||'não informado'],['Equipe',p.teamSize||'não informada'],['Prioridade',p.priority||'normal'],['Pagamento',p.paymentMethod||'não informado'],['Competência',p.competencia||'não informada'],['Escopo',p.scopeItems||'não informado'],['Referência contratual',p.legalContractFile||'não informada']].map(([k,v])=>`<div><dt>${k}</dt><dd>${k==='Referência contratual'?contractDocumentRows(p):esc(v)}</dd></div>`).join('')}</dl>`);$('#submit').hidden=true;$('#cancel').textContent='Fechar'}
function billing(code){const p=data.proposals.find(p=>p.code===code);editing=code;showModal('readonly','Detalhes do faturamento',`<div class="detail-title"><h3>${esc(p.campaign)}</h3><p>${esc(p.client)} · ${esc(displayProtocol(p))}</p></div><dl class="detail-grid"><div><dt>Valor contratado</dt><dd>${money(p.netValue)}</dd></div><div><dt>Saldo pendente</dt><dd>${money(p.netValue-p.receivedValue)}</dd></div><div><dt>Documentos do contrato</dt><dd>${contractDocumentRows(p)}</dd></div></dl><div class="billing-tools"><button type="button" class="button secondary" id="add-invoice">Emitir parcela</button><button type="button" class="button primary" id="add-receipt" ${p.netValue<=p.receivedValue?'disabled':''}>Registrar baixa</button></div><section class="billing-section"><h3>Parcelas emitidas</h3>${(p.invoices||[]).map(i=>`<article><b>${esc(i.code)} · ${money(i.amount)}</b><p>Vencimento: ${day(i.dueDate)} · saldo ${money(invoiceBalance(p,i))}</p>${i.openingCredit?`<p>Recebimento anterior alocado: ${money(i.openingCredit)}.</p>`:''}<p>Contrato: ${esc(i.contractReference)} · fornecedor: ${esc(i.supplierName)} · ${esc(i.supplierDocument)}</p>${badge(invoiceBalance(p,i)===0?'Liquidado':i.dueDate<today()?'Vencida':'A vencer')}</article>`).join('')||'<p>Não há parcelas cadastradas. Nenhum vencimento será presumido.</p>'}</section><section class="billing-section"><h3>Histórico de recebimentos</h3>${p.receivedValue>sum(p.receipts||[],'amount')?`<p>Saldo recebido anterior: ${money(p.receivedValue-sum(p.receipts||[],'amount'))}. Os exemplos anteriores não possuem comprovantes armazenados.</p>`:''}${(p.receipts||[]).map((r,i)=>`<article><b>${money(r.amount)} · ${day(r.date)}</b><p>${esc(r.invoiceCode?'parcela '+r.invoiceCode:'recebimento sem parcela')}</p>${r.attachment?`${fileRow(p.code,r.attachment,'proof',i)}`:`<small>${r.noAttachment?'Dispensa de anexo marcada pelo usuário.':'Registro anterior sem comprovante disponível.'}</small>`}</article>`).join('')||'<p>Nenhum novo recebimento registrado.</p>'}</section>`);$('#submit').hidden=true;$('#cancel').textContent='Fechar';$('#add-invoice').onclick=()=>{$('#modal').close();openInvoice(code)};$('#add-receipt').onclick=()=>{$('#modal').close();openReceipt(code)};bindFileDownloads($('#fields'))}
function openInvoice(code){const p=data.proposals.find(p=>p.code===code),remaining=Math.round((p.netValue-sum(p.invoices||[],'amount'))*100)/100;if(remaining<=0){toast('O valor contratado já foi faturado integralmente.');return}editing=code;showModal('invoice','Emitir parcela',`<div class="info-strip">Projeto ${esc(displayProtocol(p))}<br>Disponível para faturar: ${money(remaining)}</div>`+field('amount','Valor da parcela (R$)','','number',`required min="0.01" max="${remaining}" step="0.01"`)+field('dueDate','Vencimento','','date','required')+field('contractReference','Referência do contrato',p.legalContractFile||displayProtocol(p),'text','required')+field('supplierName','Nome do fornecedor',data.company.legalName,'text','required')+field('supplierDocument','CNPJ do fornecedor',data.company.cnpj,'text','required'),'Emitir parcela')}
function openReceipt(code){const p=data.proposals.find(p=>p.code===code);editing=code;const available=(p.invoices||[]).filter(i=>invoiceBalance(p,i)>0);if(p.invoices?.length&&!available.length){toast('Todas as parcelas emitidas estão liquidadas. Emita a parcela do saldo restante.');return}showModal('receipt','Registrar baixa',`<div class="info-strip">${esc(p.campaign)}<br>Saldo disponível: ${money(p.netValue-p.receivedValue)}. Anexe um comprovante ou marque a dispensa.</div>`+(available.length?selectField('invoiceCode','Parcela',available.map(i=>[i.code,`${i.code} · saldo ${money(invoiceBalance(p,i))}`]),available[0].code,'required'):'<p class="full-width">Recebimento antecipado, sem parcela emitida.</p>')+field('amount','Valor recebido (R$)','','number',`required min="0.01" max="${p.netValue-p.receivedValue}" step="0.01"`)+field('paymentDate','Data do pagamento',today(),'date','required')+field('attachment','Comprovante de pagamento','','file','accept="application/pdf,image/png,image/jpeg" required')+`<label class="checkbox-field full-width"><input name="noAttachment" type="checkbox">Não inserir anexos</label><p class="field-help full-width">PDF, PNG ou JPG com até 2 MB. A dispensa ficará registrada no histórico da baixa.</p>`,'Confirmar baixa');$('#fields [name="noAttachment"]').onchange=e=>{const file=$('#fields [name="attachment"]');file.required=!e.target.checked;file.disabled=e.target.checked;if(e.target.checked)file.value=''}}
function openDocument(code){editing=code;showModal('document','Armazenar contrato',field('attachment','Documento contratual','','file','required accept="application/pdf,image/png,image/jpeg"')+'<p class="field-help full-width">PDF, PNG ou JPG, até 2 MB por arquivo. O documento será armazenado neste workspace e poderá ser baixado no módulo Contratos.</p>','Armazenar documento')}
async function readAttachment(file){if(!file)throw Error('Selecione um arquivo.');if(!['application/pdf','image/png','image/jpeg'].includes(file.type)||file.size>2000000||!file.size)throw Error('Anexe PDF, PNG ou JPG com até 2 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return {id:crypto.randomUUID(),name:file.name,type:file.type,content:btoa(binary),uploadedAt:new Date().toISOString()}}
function downloadAttachment(a){const blob=new Blob([Uint8Array.from(atob(a.content),c=>c.charCodeAt(0))],{type:a.type});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let draftMenu=null;
function openMenu(){draftMenu=structuredClone(prefs);showModal('menu','Personalizar menu',menuFields(),'Aplicar organização');bindMenu()}
