function contractTemplates(){const saved=data.company.contractTemplates||[];return [...defaultContractTemplates.filter(t=>!saved.some(x=>x.id===t.id)),...saved]}
function contractTemplateField(p){const options=[['','Selecionar depois'],...(p.contractTemplate?[['snapshot',p.contractTemplate.name+' · versão selecionada '+p.contractTemplate.version]]:[]),...contractTemplates().map(t=>[t.id,t.name+' · versão '+t.version])];return selectField('contractTemplateId','Modelo de contrato',options,p.contractTemplate?'snapshot':p.contractTemplateId||'')}
function templateView(){return `<section class="panel"><div class="panel-head"><h2>Modelos de contrato</h2></div><p class="template-catalog-note">Modelos-base editáveis por serviço e perfil de cliente. Revise o escopo e as condições específicas antes da assinatura.</p><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Versão</th><th>Atualizado</th><th>Ação</th></tr></thead><tbody>${contractTemplates().map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${t.version}</td><td>${day(t.updatedAt)}</td><td><button class="text-link" data-template-edit="${t.id}">Editar modelo</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nenhum modelo cadastrado. Use Novo modelo para adicionar o texto contratual da organização.</td></tr>'}</tbody></table></div></section>`}
function openTemplate(id){const t=contractTemplates().find(t=>t.id===id);editing=id||null;showModal('template',t?'Editar modelo':'Novo modelo',field('templateName','Nome do modelo',t?.name||'','text','required maxlength="120"')+`<label class="full-width">Importar texto do modelo (.txt)<input type="file" id="template-import" accept="text/plain,.txt"></label><label class="full-width">Texto e cláusulas<textarea name="templateBody" rows="16" maxlength="60000" required>${esc(t?.body||'## Objeto\n{{escopo}}\n\n## Condições comerciais\nValor: {{valor}}. Forma de pagamento: {{pagamento}}.\n\n## Prazo\nEntrega prevista para {{entrega}}.')}</textarea></label><div class="template-help full-width"><b>Campos disponíveis</b><p>Use ## para títulos de cláusulas e linhas em branco para separar parágrafos. Importe o texto aprovado pela organização; o arquivo original anexado não é alterado.</p><small>${Object.entries(contractVariables).map(([k,v])=>esc('{{'+k+'}}')+' · '+v).join('<br>')}</small></div>`,'Salvar modelo');$('#template-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>200000){$('#form-error').textContent='Selecione um TXT de até 200 KB.';return}$('#fields [name="templateBody"]').value=await file.text()}}
function validateTemplateBody(body){if(!body.trim()||body.length>60000)throw Error('Informe o texto do modelo com até 60.000 caracteres.');if(body.replace(/{{\s*[^{}]+?\s*}}/g,'').match(/{{|}}/))throw Error('Há marcadores incompletos no modelo.');const unknown=[...body.matchAll(/{{\s*([^{}]+?)\s*}}/g)].map(m=>m[1]).filter(k=>!Object.hasOwn(contractVariables,k));if(unknown.length)throw Error('Campos não reconhecidos: '+[...new Set(unknown)].join(', '))}
async function saveTemplate(){const f=new FormData($('#form')),name=String(f.get('templateName')||'').trim(),body=String(f.get('templateBody')||'');if(!name)throw Error('Informe o nome do modelo.');validateTemplateBody(body);const list=data.company.contractTemplates??=[],existing=list.find(t=>t.id===editing),base=existing||contractTemplates().find(t=>t.id===editing);const entry={id:base?.id||crypto.randomUUID(),name,body,version:(base?.version||0)+1,updatedAt:new Date().toISOString()};if(existing)Object.assign(existing,entry);else list.push(entry);if(await save('O modelo de contrato foi salvo.')){$('#modal').close();render()}}
function resolvedContract(p,t){validateTemplateBody(t.body);const c=data.clients.find(c=>String(c.code)===String(p.clientCode))||{},company=data.company,values={cliente:c.legalName||p.client,cnpj_cliente:c.cnpj,endereco_cliente:c.address,empresa:company.legalName||company.fantasyName,cnpj_empresa:company.cnpj,endereco_empresa:company.address,projeto:p.campaign,protocolo:displayProtocol(p),valor:money(p.netValue),entrega:p.deliveryDate?day(p.deliveryDate):'',escopo:p.scopeItems,pagamento:p.paymentMethod,responsavel:p.responsible};const missing=[...t.body.matchAll(/{{\s*([^{}]+?)\s*}}/g)].map(m=>m[1]).filter(k=>!values[k]);if(missing.length)throw Error('Complete os dados antes de gerar: '+[...new Set(missing)].map(k=>contractVariables[k]).join(', '));const text=t.body.replace(/{{\s*([^{}]+?)\s*}}/g,(_,k)=>values[k]);const blocks=[];for(const part of text.split(/(?=^## )/m)){const lines=part.trim().split('\n'),heading=lines[0]?.startsWith('## ')?lines.shift().slice(3):'';if(lines.join('').trim()||heading)blocks.push({heading,text:lines.join('\n')})}return {title:p.campaign,protocol:displayProtocol(p),client:values.cliente,facts:[['Contratante',values.cliente+' · CNPJ '+(values.cnpj_cliente||'não informado')],['Contratada',values.empresa+' · CNPJ '+(values.cnpj_empresa||'não informado')],['Projeto',displayProtocol(p)],['Modelo',t.name+' · versão '+t.version]],blocks}}
function openGeneratedContract(code){const p=data.proposals.find(p=>p.code===code);if(!contractTemplates().length&&!p.contractTemplate){toast('Cadastre um modelo em Contratos > Modelos de contrato.');navigate('templates');return}editing=code;const options=[...(p.contractTemplate?[['snapshot',p.contractTemplate.name+' · versão selecionada '+p.contractTemplate.version]]:[]),...contractTemplates().map(t=>[t.id,t.name+' · versão '+t.version])];showModal('generated-contract','Prévia do contrato',selectField('generateTemplate','Modelo para emissão',options,p.contractTemplate?'snapshot':options[0][0])+`<div id="contract-preview" class="contract-preview full-width"></div>`,'Gerar e armazenar PDF');const refresh=()=>{try{const id=$('#fields [name="generateTemplate"]').value,t=id==='snapshot'?p.contractTemplate:contractTemplates().find(x=>x.id===id),doc=resolvedContract(p,t);$('#contract-preview').innerHTML=`<h2>${esc(doc.title)}</h2>${doc.facts.map(([k,v])=>`<p><b>${esc(k)}:</b> ${esc(v)}</p>`).join('')}${doc.blocks.map(b=>`<section><h3>${esc(b.heading)}</h3><p>${esc(b.text)}</p></section>`).join('')}`;$('#form-error').textContent='';$('#submit').disabled=false}catch(e){$('#contract-preview').textContent='Preencha os dados indicados para visualizar o contrato.';$('#form-error').textContent=e.message;$('#submit').disabled=true}};$('#fields [name="generateTemplate"]').onchange=refresh;refresh()}
async function saveGeneratedContract(){const p=data.proposals.find(p=>p.code===editing),id=new FormData($('#form')).get('generateTemplate'),t=id==='snapshot'?p.contractTemplate:contractTemplates().find(x=>x.id===id),doc=resolvedContract(p,t),bytes=window.OrionBillingPDF.build(data.company,[],{date:today(),document:doc});let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const attachment={id:crypto.randomUUID(),name:'contrato-'+displayProtocol(p)+'-v'+t.version+'.pdf',type:'application/pdf',content:btoa(binary),uploadedAt:new Date().toISOString(),templateId:t.id,templateVersion:t.version};(p.documents??=[]).push(attachment);if(await save('O contrato foi gerado e armazenado.')){$('#modal').close();render();downloadAttachment(attachment)}}

let searchTags=[];
const proposalPages=['painel','comercial','pendentes','ordens','kanban','entregas','contratos','faturamento','indicadores'];
function matchesSearchTags(p){return searchTags.every(t=>t.key==='client'?String(p.clientCode)===t.value:t.key==='status'?p.status===t.value:t.key==='attachments'?(Boolean((p.documents||[]).length||(p.receipts||[]).some(r=>r.attachment))===(t.value==='yes')):t.key==='from'?emissionDate(p)>=t.value:t.key==='to'?emissionDate(p)<=t.value:true)}
function renderSearchTags(){let holder=$('#search-tags');if(!holder){holder=document.createElement('span');holder.id='search-tags';$('.search').insertBefore(holder,$('#search'))}holder.innerHTML=searchTags.map((t,i)=>{const label=t.key==='client'?data?.clients.find(c=>String(c.code)===t.value)?.name||t.value:t.key==='status'?t.value:t.key==='attachments'?(t.value==='yes'?'Com anexos':'Sem anexos'):(t.key==='from'?'Desde ':'Até ')+day(t.value);return `<span class="search-token"><span>${esc(label)}</span><button type="button" data-remove-search-tag="${i}" aria-label="Remover filtro ${esc(label)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m7 7 10 10M17 7 7 17"/></svg></button></span>`}).join('');holder.querySelectorAll('[data-remove-search-tag]').forEach(b=>b.onclick=e=>{e.preventDefault();searchTags.splice(Number(b.dataset.removeSearchTag),1);renderSearchTags();render();captureTabView()})}
const searchFacetButton=document.createElement('button');searchFacetButton.type='button';searchFacetButton.className='search-facet-button';searchFacetButton.setAttribute('aria-label','Escolher filtros da pesquisa');searchFacetButton.innerHTML='<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 4h14l-5.5 6v5l-3 2v-7L3 4Z"/></svg>';$('.search').append(searchFacetButton);
searchFacetButton.onclick=e=>{e.preventDefault();const val=k=>searchTags.find(t=>t.key===k)?.value||'';let fields='';if(proposalPages.includes(active)){fields+=selectField('client','Cliente',[['','Todos os clientes'],...data.clients.map(c=>[String(c.code),c.name])],val('client'));fields+=selectField('status','Situação',[['','Todas as situações'],...['Em negociação','Enviado','Aprovado','Recusado','Cancelado'].map(x=>[x,x])],val('status'));fields+=selectField('attachments','Documentos e comprovantes',[['','Com ou sem anexos'],['yes','Com anexos'],['no','Sem anexos']],val('attachments'))}if(proposalPages.includes(active)||active==='agenda')fields+=field('from',active==='agenda'?'Compromissos desde':'Emissão desde',val('from'),'date')+field('to','Até',val('to'),'date');if(!fields){toast('Neste módulo, pesquise por texto. Não há filtros adicionais aplicáveis.');return}showModal('search-facets','Filtrar pesquisa',fields,'Aplicar filtros')};

function snapshotOrganization(){const company=structuredClone(data.company);delete company.contractTemplates;return company}

const financialHelp=[['Valor contratado','Soma dos valores dos orçamentos aprovados, mesmo que nenhuma parcela tenha sido emitida ou paga.','Exemplo: um projeto aprovado de R$ 10.000 representa R$ 10.000 contratados.'],['Valor faturado','Soma das parcelas emitidas para os projetos aprovados. Representa a cobrança registrada no ERP, não necessariamente uma nota fiscal emitida nem pagamento confirmado.','Exemplo: duas parcelas de R$ 5.000 totalizam R$ 10.000 faturados, mesmo que o cliente ainda não tenha pago.'],['Valor recebido','Total já registrado como recebido, incluindo saldos históricos e novas baixas. Emitir uma parcela não aumenta esse valor.','Exemplo: se apenas uma parcela de R$ 5.000 foi paga, o recebido é R$ 5.000, ainda que o faturado seja R$ 10.000.'],['Saldo pendente','Valor contratado menos o recebido. Inclui montantes que podem ainda não ter parcelas emitidas.','Exemplo: R$ 10.000 contratados menos R$ 5.000 recebidos resultam em R$ 5.000 pendentes. Não significa que todo o saldo esteja vencido.'],['Parcelas a vencer','Soma dos saldos das parcelas cujo vencimento é hoje ou uma data futura. Considera apenas parcelas efetivamente cadastradas.','Valores contratados sem parcela emitida não entram aqui. O recebimento parcial reduz o saldo da parcela.'],['Parcelas vencidas','Soma dos saldos das parcelas com vencimento anterior a hoje. Parcelas liquidadas não entram no total.','O atraso é calculado pela data cadastrada na parcela. Confira a cobrança e os recebimentos antes de registrar uma nova baixa.']];
async function copyCompanyValue(value){try{await navigator.clipboard.writeText(value);toast('Dado copiado.')}catch{const input=document.createElement('textarea');input.value=value;document.body.append(input);input.select();const ok=document.execCommand('copy');input.remove();toast(ok?'Dado copiado.':'Não foi possível copiar este dado.')}}
function companyCopyButton(value){const b=document.createElement('button');b.type='button';b.className='company-copy';b.setAttribute('aria-label','Copiar '+value);b.title='Copiar';b.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="8" y="8" width="12" height="13" rx="1"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h3"/></svg>';b.onpointerdown=e=>e.stopPropagation();b.onclick=e=>{e.preventDefault();e.stopPropagation();copyCompanyValue(typeof value==='function'?value():value)};return b}
function decorateCompanyCopies(root){if(!root||!data)return;const values=new Set();for(const item of [data.company,...data.clients,...data.proposals.flatMap(p=>[{address:p.location},...(p.invoices||[]).map(i=>({legalName:i.supplierName,cnpj:i.supplierDocument}))])])for(const [key,value]of Object.entries(item||{}))if(['name','fantasyName','legalName','cnpj','address','contacts','contact','email','phone','stateRegistration','municipalRegistration','cnae','municipalCode','fiscalEmail','addressNumber','addressComplement','district','city','state','postalCode','branchName'].includes(key)&&value!=null&&String(value).length>=2)values.add(String(value));const ordered=[...values].sort((a,b)=>b.length-a.length),nodes=[],walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement.closest('button,input,textarea,select,script,style,svg,.copy-company-value,.protocol-value,.template-help,.metric'))continue;const exact=node.textContent.trim();if(values.has(exact))nodes.push([node,exact]);else{const found=ordered.find(v=>v.length>4&&node.textContent.includes(v));if(found)nodes.push([node,found])}}for(const [node,value]of nodes){const text=node.textContent,index=text.indexOf(value),fragment=document.createDocumentFragment(),wrap=document.createElement('span');wrap.className='copy-company-value';const label=document.createElement('span');label.textContent=value;wrap.append(label,companyCopyButton(value));fragment.append(document.createTextNode(text.slice(0,index)),wrap,document.createTextNode(text.slice(index+value.length)));node.replaceWith(fragment)}root.querySelectorAll('.organization-form input,.organization-form select').forEach(input=>{if(input.parentElement.querySelector('.company-copy'))return;const button=companyCopyButton('campo');button.setAttribute('aria-label','Copiar '+(input.parentElement.childNodes[0]?.textContent||'dado da empresa'));button.onclick=e=>{e.preventDefault();copyCompanyValue(input.tagName==='SELECT'?input.selectedOptions[0]?.textContent||input.value:input.value)};input.after(button)})}
function initChartPanels(){if(active!=='indicadores')return;document.querySelectorAll('.analytics-grid>.panel').forEach((panel,index)=>{const heading=panel.querySelector('.panel-head'),title=heading?.querySelector('h2');if(!heading||!title)return;const details=document.createElement('details');details.className='panel expandable-chart';const summary=document.createElement('summary');summary.textContent=title.textContent;details.append(summary);const body=document.createElement('div');body.className='expanded-chart-body';[...panel.children].filter(c=>c!==heading).forEach(c=>body.append(c));const explanations=['Valores agrupados pelo mês de emissão do orçamento. O recebido está associado aos orçamentos dessa base, não é um extrato por data de pagamento.','Quantidade de orçamentos em cada situação comercial. A distribuição inclui negociações e recusas, não apenas contratos aprovados.','Quantidade de ordens em cada etapa do Kanban. Projetos sem ordem emitida ficam fora desta distribuição.','Indicadores calculados sobre o período selecionado. Conversão usa a quantidade aprovada; ticket médio divide o contratado pelo número de aprovados.'];const note=document.createElement('p');note.className='chart-explanation';note.textContent=explanations[index]||'';body.prepend(note);const list=filtered(),breakdown=document.createElement('dl');breakdown.className='chart-breakdown';let rows=[];if(index===0){const months=[...new Set(list.map(p=>emissionDate(p).slice(0,7)).filter(Boolean))].sort().slice(-12);rows=months.map(month=>{const items=list.filter(p=>emissionDate(p).startsWith(month));return [month.split('-').reverse().join('/'),items.length+' orçamento(s) · emitido '+money(sum(items,'netValue'))+' · recebido '+money(sum(items,'receivedValue'))]})}if(index===1){rows=['Em negociação','Enviado','Aprovado','Recusado','Cancelado'].map(status=>{const count=list.filter(p=>p.status===status).length;return [status,count+' · '+Math.round(count/(list.length||1)*100)+'% da base']})}if(index===2){const orders=list.filter(p=>p.projectCode);rows=stages.map(stage=>{const count=orders.filter(p=>(p.erpStage||stages[0])===stage).length;return [stage,count+' · '+Math.round(count/(orders.length||1)*100)+'% das ordens']})}breakdown.innerHTML=rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('');if(rows.length)body.append(breakdown);details.append(body);panel.replaceWith(details)})}

// Destinos de navegação usam a mesma nomenclatura do menu, abas e histórico.
function decorateNavigation(){document.querySelectorAll('#content [data-nav]').forEach(button=>{const id=button.dataset.nav,path=pagePath(id),destination='Ir para '+path;button.title=destination;button.setAttribute('aria-label',destination);if(button.matches('.text-link'))button.textContent=destination;else{const caption=document.createElement('small');caption.className='navigation-destination';caption.textContent=destination;button.append(caption)}});document.querySelectorAll('[data-approval-open]').forEach(b=>{b.textContent='Ir para Aprovações';b.title='Abrir o orçamento no módulo Aprovações'});document.querySelectorAll('[data-detail]').forEach(b=>{b.textContent='Consultar registro';b.title='Abrir detalhes sem alterar os dados'});document.querySelectorAll('[data-issue]').forEach(b=>b.title='Abrir formulário de emissão da ordem de serviço')}

function setMobileMenu(open){document.body.classList.toggle('mobile-menu-open',open);document.querySelector('#mobile-menu').setAttribute('aria-expanded',String(open));document.querySelector('#mobile-menu').setAttribute('aria-label',open?'Fechar menu':'Abrir menu');document.querySelector('#mobile-menu-shade').hidden=!open}
document.querySelector('#mobile-menu').onclick=()=>setMobileMenu(!document.body.classList.contains('mobile-menu-open'));
document.querySelector('#mobile-menu-shade').onclick=()=>setMobileMenu(false);
document.addEventListener('keydown',e=>{if(e.key==='Escape')setMobileMenu(false)});
matchMedia('(min-width:769px)').addEventListener('change',e=>{if(e.matches)setMobileMenu(false)});

// Transporte em partes: nenhum anexo é removido para contornar o limite da plataforma.
async function fetchWorkspace(){const response=await fetch('/api/workspace');if(!response.ok)throw Error('Não foi possível carregar o workspace ('+response.status+').');const meta=await response.json();if(!meta.parts)return meta;const pieces=[];for(let part=0;part<meta.parts;part++){const r=await fetch('/api/workspace?part='+part+'&revision='+meta.revision);if(!r.ok)throw Error('Os dados mudaram durante a leitura ou a conexão foi interrompida. Recarregue.');pieces.push((await r.json()).text)}return {revision:meta.revision,data:JSON.parse(pieces.join(''))}}
async function uploadWorkspace(next,expected){const text=JSON.stringify(next);if(new TextEncoder().encode(text).length>16000000)throw Error('Workspace excede 16 MB. Solicite ampliação do armazenamento antes de anexar novos arquivos.');const pieces=[];for(let start=0;start<text.length;){let end=Math.min(start+250000,text.length);if(end<text.length&&text.charCodeAt(end-1)>=0xD800&&text.charCodeAt(end-1)<=0xDBFF)end--;pieces.push(text.slice(start,end));start=end}const uploadId=crypto.randomUUID(),total=pieces.length,headers={'Content-Type':'application/json','If-Match':String(expected)};for(let part=0;part<total;part++){const response=await fetch('/api/upload',{method:'PUT',headers,body:JSON.stringify({uploadId,part,total,text:pieces[part]})});if(!response.ok)return response}return fetch('/api/commit',{method:'PUT',headers,body:JSON.stringify({uploadId})})}
